/* WebTorrent browser server (classic service worker).
 * waitUntil() is required so Firefox does not mark the worker active
 * before this page is actually controlled — otherwise /webtorrent/* hits the origin and 404s.
 */
'use strict'

const portTimeoutDuration = 5000

self.addEventListener('install', event => {
  event.waitUntil(self.skipWaiting())
})

self.addEventListener('activate', event => {
  event.waitUntil(self.clients.claim())
})

self.addEventListener('fetch', event => {
  const prefix = self.registration.scope + 'webtorrent/'
  if (!event.request.url.includes(prefix)) return
  event.respondWith(
    handleFetch(event).catch(() => new Response('', { status: 204 }))
  )
})

async function handleFetch (event) {
  const { url } = event.request
  const prefix = self.registration.scope + 'webtorrent/'
  if (url.includes(prefix + 'keepalive/')) return new Response('', { status: 204 })
  // Firefox errors if this probe uses an empty ReadableStream (Failed to load '').
  // A real body is enough; Firefox still cannot cancel SW streams, so streaming
  // uses the timeout path in serve() either way.
  if (url.includes(prefix + 'cancel/')) return new Response(new Uint8Array(0))
  return serve(event.request)
}

async function serve (request) {
  const { url, method, headers, destination } = request
  const clientList = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
  if (!clientList.length) return new Response('no webtorrent client', { status: 503 })

  const [data, port] = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('webtorrent client timeout')), 10000)
    for (const client of clientList) {
      const { port1, port2 } = new MessageChannel()
      port1.onmessage = ({ data }) => {
        clearTimeout(timer)
        resolve([data, port1])
      }
      client.postMessage({
        url,
        method,
        headers: Object.fromEntries(headers.entries()),
        scope: self.registration.scope,
        destination,
        type: 'webtorrent'
      }, [port2])
    }
  })

  let timeOut = null
  const cleanup = () => {
    try { port.postMessage(false) } catch {}
    clearTimeout(timeOut)
    port.onmessage = null
  }

  if (!data || data.body !== 'STREAM') {
    cleanup()
    return new Response(data && data.body, data || { status: 404 })
  }

  return new Response(new ReadableStream({
    pull (controller) {
      return new Promise(resolve => {
        port.onmessage = ({ data }) => {
          if (data) {
            controller.enqueue(data)
          } else {
            cleanup()
            controller.close()
          }
          resolve()
        }
        // Firefox cannot cancel ReadableStreams in a service worker.
        clearTimeout(timeOut)
        if (destination !== 'document') {
          timeOut = setTimeout(() => {
            cleanup()
            resolve()
          }, portTimeoutDuration)
        }
        port.postMessage(true)
      })
    },
    cancel () {
      cleanup()
    }
  }), data)
}
